package com.hssa.auth.service.impl; import com.hssa.auth.entity.RefreshToken; import com.hssa.auth.repository.RefreshTokenRepository; import com.hssa.auth.repository.UserRepository;
import com.hssa.auth.service.RefreshTokenService;
import com.hssa.exception.ResourceNotFoundException;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.time.temporal.ChronoUnit; import java.util.UUID; @Service public class RefreshTokenServiceImpl implements RefreshTokenService { private final RefreshTokenRepository refreshTokenRepository; private final UserRepository userRepository; @Value("${application.security.jwt.refresh-token.expiration}") private long refreshTokenDurationMs; public RefreshTokenServiceImpl(RefreshTokenRepository refreshTokenRepository, UserRepository userRepository) { this.refreshTokenRepository = refreshTokenRepository; this.userRepository = userRepository; } @Override public RefreshToken createRefreshToken(UUID userId) { RefreshToken refreshToken = new RefreshToken(); refreshToken.setUser(userRepository.findById(userId).orElseThrow(() -> new ResourceNotFoundException("User not found"))); refreshToken.setToken(UUID.randomUUID().toString()); refreshToken.setExpiresAt(LocalDateTime.now().plus(refreshTokenDurationMs, ChronoUnit.MILLIS)); return refreshTokenRepository.save(refreshToken); } @Override public RefreshToken verifyExpiration(RefreshToken token) { if (token.getExpiresAt().isBefore(LocalDateTime.now())) { refreshTokenRepository.delete(token); throw new RuntimeException("Refresh token was expired. Please make a new signin request"); } return token; } @Override @Transactional public void revokeAllUserTokens(UUID userId) { var tokens = refreshTokenRepository.findByUser_IdAndIsRevokedFalse(userId); tokens.forEach(token -> { token.setRevoked(true); token.setRevokedAt(LocalDateTime.now()); }); refreshTokenRepository.saveAll(tokens); } }
